//! Finite lock polynomials from lock fillings.

use std::collections::BTreeMap;

use sym_poly_core::{Ring, Ssaf};

use crate::multipoly::MultiPoly;

/// Compute the finite lock polynomial indexed by a weak composition.
///
/// This is the Assaf--Searles lock polynomial: the Kohnert polynomial of the
/// right-justified diagram with `alpha[i]` cells in row `i + 1`, so that
/// `lock_(2,0) = x_1^2` and a lock with one nonzero row is a key polynomial
/// (in the standard index of [`mod@crate::key_polynomial`]).
///
/// It is computed as the weight enumerator of the lock fillings generated by
/// [`Ssaf::lock_fillings`]. As for [`Ssaf::key_fillings`], the filling shape is
/// the reverse of the weak composition indexing the polynomial.
pub fn lock_polynomial<C: Ring>(alpha: &[u32]) -> MultiPoly<C> {
    let num_vars = alpha.len();
    let mut terms: BTreeMap<Vec<u32>, C> = BTreeMap::new();
    let filling_shape: Vec<u32> = alpha.iter().rev().copied().collect();

    for filling in Ssaf::lock_fillings(&filling_shape) {
        let entry = terms.entry(filling.weight_vector()).or_insert_with(C::zero);
        *entry = entry.clone() + C::one();
    }

    MultiPoly::from_terms(num_vars, terms)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::kohnert::{kohnert_polynomial_with_num_vars, Cell, Diagram};

    #[test]
    fn test_lock_polynomial_single_column_pair() {
        let lock: MultiPoly<i64> = lock_polynomial(&[1, 1]);
        assert_eq!(lock.terms().len(), 1);
        assert_eq!(lock.coefficient(&[1, 1]), 1);
    }

    #[test]
    fn test_lock_polynomial_single_bottom_row_is_monomial() {
        // Cells in row 1 cannot move: lock_(2,0) = x_1^2.
        let lock: MultiPoly<i64> = lock_polynomial(&[2, 0]);
        assert_eq!(lock.terms().len(), 1);
        assert_eq!(lock.coefficient(&[2, 0]), 1);
    }

    #[test]
    fn test_lock_polynomial_matches_right_justified_kohnert() {
        // Assaf--Searles: locks are Kohnert polynomials of right-justified diagrams.
        for a in 0..=3u32 {
            for b in 0..=(3 - a) {
                for c in 0..=(3 - a - b) {
                    let alpha = [a, b, c];
                    let width = *alpha.iter().max().unwrap() as usize;
                    let mut diagram = Diagram::new();
                    for (idx, &len) in alpha.iter().enumerate() {
                        for col in (width + 1 - len as usize)..=width {
                            if len > 0 {
                                diagram.insert(Cell { col, row: idx + 1 });
                            }
                        }
                    }
                    let kohnert: MultiPoly<i64> =
                        kohnert_polynomial_with_num_vars(&diagram, 100_000, alpha.len())
                            .expect("Kohnert diagrams");
                    let lock: MultiPoly<i64> = lock_polynomial(&alpha);
                    assert_eq!(lock.terms(), kohnert.terms(), "alpha = {alpha:?}");
                }
            }
        }
    }

    #[test]
    fn test_lock_polynomial_single_top_row_is_key() {
        let lock: MultiPoly<i64> = lock_polynomial(&[0, 2]);
        assert_eq!(lock.terms().len(), 3);
        assert_eq!(lock.coefficient(&[2, 0]), 1);
        assert_eq!(lock.coefficient(&[1, 1]), 1);
        assert_eq!(lock.coefficient(&[0, 2]), 1);
    }

    #[test]
    fn test_lock_polynomial_counts_lock_fillings_by_weight() {
        let alpha = [2, 1, 1];
        let lock: MultiPoly<i64> = lock_polynomial(&alpha);
        let filling_count = Ssaf::lock_fillings(&alpha).len() as i64;
        let coefficient_sum: i64 = lock.terms().values().sum();

        assert_eq!(coefficient_sum, filling_count);
        assert!(lock
            .terms()
            .keys()
            .all(|weight| weight.iter().sum::<u32>() == alpha.iter().sum()));
    }
}
